{
  "name": "TOPTICA iBeam 智能二极管激光器",
  "name_en": "TOPTICA iBeam Smart Diode Laser",
  "manufacturer": "TOPTICA",
  "description": "TOPTICA iBeam 是一款紧凑型智能二极管激光光源，可通过串口控制激光开关和输出功率，并读取实际输出状态。它常用于显微镜激发照明、光学实验以及需要稳定连续激光输出的实验室场景。",
  "description_en": "The TOPTICA iBeam is a compact smart diode laser source with serial control for laser on/off operation, output power setting, and status readback. It is commonly used for microscope excitation, optical experiments, and other laboratory applications requiring stable continuous laser output.",
  "actions": [
    {
      "action_name": "auto-command",
      "description": "发送原始设备命令并读取激光器返回结果。",
      "description_en": "Send a raw device command and read the laser's reply."
    },
    {
      "action_name": "auto-laser_on",
      "description": "开启激光驱动，使激光器输出激光。",
      "description_en": "Turn on the laser driver to enable laser output."
    },
    {
      "action_name": "auto-laser_off",
      "description": "关闭激光驱动，停止激光输出。",
      "description_en": "Turn off the laser driver to stop laser output."
    },
    {
      "action_name": "auto-set_normal_channel_power",
      "description": "设置正常工作通道的激光输出功率。",
      "description_en": "Set the laser output power for the normal operating channel."
    },
    {
      "action_name": "auto-show_power_uW",
      "description": "获取当前实际激光输出功率。",
      "description_en": "Get the current actual laser output power."
    },
    {
      "action_name": "auto-status_laser",
      "description": "获取激光驱动的开关状态。",
      "description_en": "Get the on/off status of the laser driver."
    },
    {
      "action_name": "auto-show_max_power",
      "description": "获取激光器可用的最大输出功率。",
      "description_en": "Get the maximum available output power of the laser."
    }
  ],
  "tag_hints": [
    "diode laser",
    "microscope illumination",
    "laser excitation",
    "serial-controlled laser",
    "continuous-wave laser",
    "optical experiments"
  ]
}

